INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('3g617yfxinoalc18lf3g617yfpwylyti', '2026-Q2', 'Jun–Jul/2026 (T2)', '2026-06-18T10:19'::timestamptz, 'Bianca Assone Rodrigues', 'bianca assone rodrigues', 'PHARUS', 'Willian Oliveira Schimidt', 0.0, 'Detrator', 3.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'Não achei que o programa teve um bom custo benefício e não me senti em um atendimento personalizado. Um monte de soluções básicas e que eu facilmente encontraria sozinha', 'Exemplo: pedi ajuda para entrar no mercado de leilão ou propostas para conseguir usar meu fgts. Ninguém me apresentou nada, não houveram sugestões, e os projetos apresentados não foram relevantes', NULL, 'não pretendo renovar, muito menos por este valor. O ROI nao bate', 'nao gostei da experiencia, esperava algo mais exclusivo, mais atenção sobre os pontos apresentados, senti que faltou clareza na explicação dos riscos que estavamos correndo ao prosseguir com as propostas apresentadas, faltou empenho da quarta via em apresentar algo "mastigado"', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '3g617yfxinoalc18lf3g617yfpwylyti', 'base mecanismos (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categ